<?php
require_once __DIR__.'/../config/auth.php';require_role(['kasir','owner']);$pageTitle='Pesanan Masuk';$menus=dbq('SELECT id,nama,stok,is_available FROM menus ORDER BY nama')->fetchAll();require __DIR__.'/../includes/admin-header.php'; ?>
<div class="flex flex-wrap items-center justify-between gap-3 mb-5"><div><p class="text-sm text-coffee/60">pesanan diperbarui otomatis setiap 5 detik.</p><p class="text-xs text-coffee/45 mt-1">gunakan kontrol di bawah untuk memperbarui status dan konfirmasi pembayaran.</p></div><a class="btn btn-coffee" href="<?= h(BASE_URL) ?>/kasir/pos.php">＋ Pesanan manual</a></div><div id="orderMessage" class="flash flash-ok hidden" role="status"></div><div id="orderLoading" class="card p-8 text-center text-sm text-coffee/60">memuat pesanan...</div><div id="ordersList" class="grid lg:grid-cols-2 2xl:grid-cols-3 gap-4"></div>
<section class="card p-5 mt-7"><div><h2 class="font-serif text-2xl">Ketersediaan menu</h2><p class="text-xs text-coffee/55 mt-1">ubah status habis / tersedia dengan cepat.</p></div><div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-3 mt-4"><?php foreach($menus as $m):?><div class="flex items-center justify-between gap-3 p-3 rounded-xl bg-white border border-coffee/10"><div><b class="text-sm"><?= h($m['nama']) ?></b><span class="block text-xs text-coffee/50">stok <?= (int)$m['stok'] ?></span></div><button type="button" class="text-xs underline" data-stock-toggle="<?= (int)$m['id'] ?>"><?= $m['is_available']?'Tandai habis':'Tersedia' ?></button></div><?php endforeach;?></div></section>
<script>
const ORDERS_API=<?= json_encode(BASE_URL.'/api/orders.php') ?>,CSRF=<?= json_encode(csrf_token()) ?>;const listEl=document.getElementById('ordersList'),loadEl=document.getElementById('orderLoading'),msgEl=document.getElementById('orderMessage');
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}function price(v){return 'Rp'+Number(v||0).toLocaleString('id-ID',{maximumFractionDigits:0})}function render(orders){loadEl.classList.add('hidden');if(!orders.length){listEl.innerHTML='<div class="card p-8 text-center text-sm text-coffee/60 lg:col-span-2 2xl:col-span-3">belum ada pesanan aktif dalam 7 hari terakhir.</div>';return}listEl.innerHTML=orders.map(o=>{const items=(o.items||[]).map(i=>`<div class="flex justify-between gap-3 text-sm py-1"><span>${esc(i.qty)}× ${esc(i.nama_menu)} ${i.opsi_json&&i.opsi_json!=='[]'?'<small class="block text-xs text-coffee/50">'+esc(i.opsi_json)+'</small>':''}</span><b class="whitespace-nowrap">${price(Number(i.harga)*Number(i.qty))}</b></div>`).join('');const statuses=['Diterima','Diproses','Siap','Selesai','Dibatalkan'];const pays=['Belum Bayar','Menunggu QRIS','Lunas','Gagal'];return `<article class="card p-5"><div class="flex items-start justify-between gap-3"><div><p class="text-xs text-coffee/50">${esc(o.created_at)}</p><h2 class="font-semibold mt-1">${esc(o.kode_pesanan)}</h2><p class="text-sm text-coffee/65 mt-1">${esc(o.nama_pelanggan)} · ${o.nomor_meja?'Meja '+esc(o.nomor_meja):'Take away'}</p></div><span class="status-pill ${o.status_pesanan==='Selesai'?'status-green':o.status_pesanan==='Siap'?'status-orange':''}">${esc(o.status_pesanan)}</span></div><div class="border-t border-coffee/10 my-3"></div><div>${items}</div>${o.catatan?'<p class="text-xs bg-cream p-2 rounded-lg mt-2">Catatan: '+esc(o.catatan)+'</p>':''}<div class="flex justify-between items-center border-t border-coffee/10 mt-3 pt-3"><span class="text-sm">Total</span><b class="text-lg">${price(o.total)}</b></div><div class="flex flex-wrap items-center justify-between gap-2 mt-2"><span class="status-pill ${o.status_bayar==='Lunas'?'status-green':o.status_bayar==='Gagal'?'status-red':'status-orange'}">${esc(o.status_bayar)}</span><a class="text-xs underline" href="${<?= json_encode(BASE_URL) ?>}/kasir/receipt.php?kode=${encodeURIComponent(o.kode_pesanan)}">Preview struk ↗</a></div><form class="api-action mt-4 grid grid-cols-[1fr_auto] gap-2" data-kind="status"><input type="hidden" name="_csrf" value="${CSRF}"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="${o.id}"><select class="field !py-2" name="status_pesanan">${statuses.map(s=>`<option ${s===o.status_pesanan?'selected':''}>${s}</option>`).join('')}</select><button class="btn btn-coffee !px-3 !py-2">Update</button></form><form class="api-action mt-2 grid grid-cols-[1fr_auto] gap-2" data-kind="payment"><input type="hidden" name="_csrf" value="${CSRF}"><input type="hidden" name="action" value="payment"><input type="hidden" name="id" value="${o.id}"><div class="grid grid-cols-2 gap-2"><select class="field !py-2" name="status_bayar">${pays.map(s=>`<option ${s===o.status_bayar?'selected':''}>${s}</option>`).join('')}</select><select class="field !py-2" name="metode_bayar"><option value="Kasir" ${o.metode_bayar==='Kasir'?'selected':''}>Kasir/tunai</option><option value="QRIS" ${o.metode_bayar==='QRIS'?'selected':''}>QRIS</option></select></div><button class="btn btn-light !px-3 !py-2">Konfirmasi bayar</button></form></article>`}).join('');document.querySelectorAll('.api-action').forEach(f=>f.addEventListener('submit',submitAction))}
async function submitAction(e){e.preventDefault();const f=e.currentTarget;const b=f.querySelector('button');b.disabled=true;try{const r=await fetch(ORDERS_API,{method:'POST',body:new FormData(f)});const d=await r.json();msgEl.textContent=d.message||'selesai';msgEl.classList.remove('hidden');if(d.ok){await refreshOrders()}else msgEl.className='flash flash-error';}catch(e){msgEl.textContent='koneksi gagal. coba lagi.';msgEl.className='flash flash-error'}finally{b.disabled=false}}
async function refreshOrders(){try{const r=await fetch(ORDERS_API+'?action=list',{cache:'no-store'});const d=await r.json();if(d.ok)render(d.orders)}catch(e){if(!listEl.children.length)loadEl.textContent='gagal memuat data. periksa koneksi.'}}refreshOrders();setInterval(refreshOrders,5000);document.querySelectorAll('[data-stock-toggle]').forEach(b=>b.addEventListener('click',async()=>{const f=new FormData();f.append('_csrf',CSRF);f.append('action','availability');f.append('id',b.dataset.stockToggle);const r=await fetch(ORDERS_API,{method:'POST',body:f}),d=await r.json();if(d.ok)location.reload();else alert(d.message)}));
</script><?php require __DIR__.'/../includes/admin-footer.php'; ?>
